package sa.bas.mobileindex;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.provider.Settings;import android.graphics.Color;import android.view.*;import android.widget.*;import android.text.*;import java.io.*;import java.util.*;import java.util.concurrent.*;import org.json.*;
public class MainActivity extends Activity {
 final int navy=Color.rgb(16,30,52),gold=Color.rgb(191,153,78); final ExecutorService worker=Executors.newSingleThreadExecutor();
 ArrayList<Item> items=new ArrayList<>(),shown=new ArrayList<>(); Spinner type,location,name,date,size,sort; EditText search; TextView status; ListView list; boolean busy=false,ready=false;
 static class Item {String path;long bytes,time;Item(String p,long b,long t){path=p;bytes=b;time=t;}String title(){return new File(path).getName();}String folder(){return new File(path).getParent();}}
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(navy);getWindow().setNavigationBarColor(navy);LinearLayout base=new LinearLayout(this);base.setOrientation(1);base.setPadding(24,32,24,8);base.setBackgroundColor(Color.rgb(245,244,240));base.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);setContentView(base);
 TextView head=new TextView(this);head.setText("فهرس الجوال");head.setTextSize(30);head.setTextColor(navy);head.setTypeface(null,1);base.addView(head);TextView sub=new TextView(this);sub.setText("ملفاتك في مكانها • فهرس محلي على هاتفك");base.addView(sub);
 LinearLayout buttons=new LinearLayout(this);base.addView(buttons);Button access=new Button(this);access.setText("السماح بالوصول");buttons.addView(access,new LinearLayout.LayoutParams(0,-2,1));access.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("الوصول للملفات المشتركة").setMessage("يلزم الإذن لفهرسة التنزيلات والمستندات والصور. التطبيق يقرأ الأسماء والمسارات والحجم والتاريخ فقط، ويحفظ الفهرس محليًا. لا يحتوي أدوات نقل أو حذف، ولا يستخدم الإنترنت.").setPositiveButton("فتح الإعدادات",(d,w)->{try{startActivity(new Intent(Settings.ACTION_MANAGE_APP_ALL_FILES_ACCESS_PERMISSION,Uri.parse("package:"+getPackageName())));}catch(Exception e){startActivity(new Intent(Settings.ACTION_MANAGE_ALL_FILES_ACCESS_PERMISSION));}}).setNegativeButton("إلغاء",null).show());Button refresh=new Button(this);refresh.setText("تحديث الفهرس");buttons.addView(refresh,new LinearLayout.LayoutParams(0,-2,1));refresh.setOnClickListener(v->scan());
 search=new EditText(this);search.setSingleLine();search.setHint("ابحث باسم الملف أو مساره…");base.addView(search);
 LinearLayout r1=new LinearLayout(this);base.addView(r1);type=spinner(r1,new String[]{"النوع: الكل","PDF","صور","فيديو","صوت","مستندات","APK","مضغوط","أخرى"});location=spinner(r1,new String[]{"الموقع: الكل"});
 LinearLayout r2=new LinearLayout(this);base.addView(r2);name=spinner(r2,new String[]{"الاسم: الكل","أسماء تحتاج مراجعة","أسماء أخرى"});date=spinner(r2,new String[]{"التاريخ: الكل","آخر يوم","آخر أسبوع","آخر شهر"});
 LinearLayout r3=new LinearLayout(this);base.addView(r3);size=spinner(r3,new String[]{"الحجم: الكل","أقل من 1 MB","من 1 إلى 100 MB","أكبر من 100 MB"});sort=spinner(r3,new String[]{"الترتيب: الأحدث","الأقدم","الاسم","الأكبر حجمًا"});
 Button clear=new Button(this);clear.setText("مسح الفلاتر");base.addView(clear);clear.setOnClickListener(v->{search.setText("");for(Spinner s:new Spinner[]{type,location,name,date,size,sort})s.setSelection(0);filter();});status=new TextView(this);status.setTextColor(navy);base.addView(status);list=new ListView(this);base.addView(list,new LinearLayout.LayoutParams(-1,0,1));list.setOnItemClickListener((p,v,pos,id)->details(shown.get(pos)));
 search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int before,int c){if(ready)filter();}public void afterTextChanged(Editable e){}});ready=true;load();
 }
 Spinner spinner(LinearLayout row,String[] choices){Spinner s=new Spinner(this);s.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,choices));row.addView(s,new LinearLayout.LayoutParams(0,56*getResources().getDisplayMetrics().densityDpi/160,1));s.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?>p,View v,int n,long id){if(ready)filter();}public void onNothingSelected(AdapterView<?>p){}});return s;}
 String kind(Item i){String n=i.title().toLowerCase(Locale.ROOT);String e=n.contains(".")?n.substring(n.lastIndexOf('.')+1):"";if(e.equals("pdf"))return "PDF";if(Arrays.asList("jpg","jpeg","png","webp","gif","heic","bmp").contains(e))return "صور";if(Arrays.asList("mp4","mkv","mov","avi","webm","3gp").contains(e))return "فيديو";if(Arrays.asList("mp3","m4a","wav","ogg","aac","flac").contains(e))return "صوت";if(e.equals("apk"))return "APK";if(Arrays.asList("zip","rar","7z","tar","gz").contains(e))return "مضغوط";if(Arrays.asList("doc","docx","xls","xlsx","ppt","pptx","txt","csv","html","json","epub").contains(e))return "مستندات";return "أخرى";}
 boolean vague(Item i){String n=i.title().replaceFirst("\\.[^.]+$","");return n.matches("(?i)(IMG|VID|AUD|DSC|Screenshot|image|file|document|download)[_ \\-]*[0-9_ \\-().]+")||n.matches("[0-9_ \\-().]+")||n.matches("(?i)[a-f0-9\\-]{20,}");}
 void filter(){if(!ready||busy)return;String q=search.getText().toString().trim().toLowerCase(Locale.ROOT);shown=new ArrayList<>();long now=System.currentTimeMillis();for(Item i:items){if(!i.path.toLowerCase(Locale.ROOT).contains(q))continue;if(type.getSelectedItemPosition()>0&&!kind(i).equals(type.getSelectedItem().toString()))continue;if(location.getSelectedItemPosition()>0&&!i.folder().equals(location.getSelectedItem().toString()))continue;int n=name.getSelectedItemPosition();if(n==1&&!vague(i)||n==2&&vague(i))continue;int d=date.getSelectedItemPosition();long days=d==1?1:d==2?7:30;if(d>0&&(i.time<=0||now-i.time>days*86400000L))continue;int z=size.getSelectedItemPosition();if(z==1&&i.bytes>=1048576||z==2&&(i.bytes<1048576||i.bytes>104857600)||z==3&&i.bytes<=104857600)continue;shown.add(i);}int s=sort.getSelectedItemPosition();shown.sort(s==2?(a,b)->a.title().compareToIgnoreCase(b.title()):s==3?(a,b)->Long.compare(b.bytes,a.bytes):s==1?(a,b)->Long.compare(a.time,b.time):(a,b)->Long.compare(b.time,a.time));status.setText(shown.size()+" من "+items.size()+" ملف • اضغط لفتح التفاصيل");ArrayList<String> labels=new ArrayList<>();for(Item i:shown)labels.add(i.title()+"\n"+kind(i)+" · "+android.text.format.Formatter.formatFileSize(this,i.bytes)+"\n"+i.folder());list.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_list_item_1,labels));}
 void locations(){String old=location.getSelectedItem()==null?"":location.getSelectedItem().toString();TreeSet<String> dirs=new TreeSet<>();for(Item i:items)dirs.add(i.folder());ArrayList<String> opts=new ArrayList<>();opts.add("الموقع: الكل");opts.addAll(dirs);location.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,opts));int idx=opts.indexOf(old);location.setSelection(Math.max(0,idx));}
 void scan(){if(busy)return;if(!Environment.isExternalStorageManager()){status.setText("اضغط السماح بالوصول أولًا، ثم فعّل الإذن وارجع للتطبيق.");return;}busy=true;status.setText("جارٍ فهرسة الملفات… يمكنك الانتظار دون تغيير ملفاتك");worker.execute(()->{ArrayList<Item> found=new ArrayList<>();int skipped=0;ArrayDeque<File> dirs=new ArrayDeque<>();dirs.add(Environment.getExternalStorageDirectory());HashSet<String> visited=new HashSet<>();while(!dirs.isEmpty()){File dir=dirs.removeFirst();try{if(!visited.add(dir.getCanonicalPath()))continue;File[] children=dir.listFiles();if(children==null){skipped++;continue;}for(File f:children){if(f.isHidden())continue;if(f.isDirectory()){if(!f.getPath().contains("/Android/data")&&!f.getPath().contains("/Android/obb"))dirs.add(f);}else if(f.isFile())found.add(new Item(f.getAbsolutePath(),f.length(),f.lastModified()));}}catch(Exception e){skipped++;}}String error="";try{JSONArray a=new JSONArray();for(Item i:found)a.put(new JSONObject().put("path",i.path).put("size",i.bytes).put("time",i.time));android.util.AtomicFile af=new android.util.AtomicFile(new File(getFilesDir(),"index.json"));FileOutputStream out=null;try{out=af.startWrite();out.write(a.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));af.finishWrite(out);}catch(Exception ex){if(out!=null)af.failWrite(out);throw ex;}}catch(Exception e){error="تعذر حفظ الفهرس";}final int inaccessible=skipped;final String err=error;runOnUiThread(()->{items=found;busy=false;locations();filter();if(inaccessible>0||!err.isEmpty())status.append("\nمجلدات غير متاحة: "+inaccessible+" "+err);getPreferences(0).edit().putLong("lastScan",System.currentTimeMillis()).apply();});});}
 void load(){worker.execute(()->{ArrayList<Item> loaded=new ArrayList<>();try{byte[] bytes=new android.util.AtomicFile(new File(getFilesDir(),"index.json")).readFully();JSONArray a=new JSONArray(new String(bytes,java.nio.charset.StandardCharsets.UTF_8));for(int j=0;j<a.length();j++){JSONObject o=a.getJSONObject(j);loaded.add(new Item(o.getString("path"),o.getLong("size"),o.getLong("time")));}}catch(Exception ignored){}runOnUiThread(()->{items=loaded;locations();filter();if(items.isEmpty())status.setText("ابدأ بالسماح بالوصول، ثم تحديث الفهرس.\nالتطبيق يفهرس التخزين المشترك فقط. الأسماء الغامضة تقدير من الاسم وليست حكمًا على المحتوى.");});});}
 void details(Item i){String stamp=i.time>0?java.text.DateFormat.getDateTimeInstance().format(new Date(i.time)):"غير معروف";new AlertDialog.Builder(this).setTitle(i.title()).setMessage(i.path+"\n\n"+android.text.format.Formatter.formatFileSize(this,i.bytes)+"\n"+stamp+"\n\nإذا نقلت الملف أو حذفته، حدّث الفهرس.").setPositiveButton("فتح الملف",(d,w)->open(i)).setNeutralButton("الموقع",(d,w)->folder(i)).setNegativeButton("إغلاق",null).show();}
 void open(Item i){if(!new File(i.path).isFile()){toast("الملف غير موجود في هذا المسار. حدّث الفهرس.");return;}Uri u=new Uri.Builder().scheme("content").authority(getPackageName()+".files").path(i.path).build();Intent intent=new Intent(Intent.ACTION_VIEW).setDataAndType(u,getContentResolver().getType(u)).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);intent.setClipData(ClipData.newRawUri("file",u));try{startActivity(Intent.createChooser(intent,"فتح بواسطة"));}catch(Exception e){toast("لا يوجد تطبيق مناسب لفتح هذا النوع، أو يلزم تجديد إذن الوصول.");}}
 void folder(Item i){String root=Environment.getExternalStorageDirectory().getAbsolutePath();String relative=i.folder().substring(root.length());if(relative.startsWith("/"))relative=relative.substring(1);Uri u=android.provider.DocumentsContract.buildDocumentUri("com.android.externalstorage.documents","primary:"+relative);Intent intent=new Intent(Intent.ACTION_VIEW).setDataAndType(u,"vnd.android.document/directory");try{startActivity(intent);}catch(Exception e){new AlertDialog.Builder(this).setTitle("موقع الملف").setMessage(i.folder()+"\n\nمدير الملفات لا يدعم فتح هذا المجلد مباشرة. افتح «ملفاتي» واتبع المسار.").setPositiveButton("نسخ المسار",(d,w)->{((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("path",i.folder()));toast("تم نسخ المسار");}).setNegativeButton("إغلاق",null).show();}}
 void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 protected void onDestroy(){worker.shutdown();super.onDestroy();}
}
